// === Tab: mySketch ===
let particles = [];
const numParticles = 3000;
const noiseScale = 0.01;
const noiseStrength = 1; // Adjust to control how much noise influences the flow
const particleLifespan = 200; // How long each particle lives for, before being respawned

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0); // Dark background
  // Initialize particles
  for (let i = 0; i < numParticles; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  // Blend mode to create trails
  blendMode(ADD);
  // faded dark background
  background(0, 5);

  blendMode(BLEND); // Reset to normal blend mode for particle rendering

  // Update and display particles
  for (let particle of particles) {
    particle.update();
    particle.display();
  }
}

class Particle {
  constructor() {
    this.pos = createVector(random(width * 0.2, width * 0.8), random(height * 0.15, height * 0.85)); // Initial position in the central area
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.maxSpeed = 2;
    this.age = 0;
  }

  update() {
    // Calculate flow field direction based on Perlin noise and mouse position
    let angle = map(noise(this.pos.x * noiseScale, this.pos.y * noiseScale), 0, 1, 0, TWO_PI * noiseStrength); // noise affects direction
    let mouseForce = p5.Vector.sub(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), this.pos);
    mouseForce.setMag(0.5); // Reduce mouse influence
    angle += mouseForce.heading(); // Add mouse direction to the angle

    this.acc = p5.Vector.fromAngle(angle); // Acceleration from angle

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.age++;

    // Respawn particle if it goes out of bounds or dies
    if (this.pos.x < 0 || this.pos.x > width || this.pos.y < 0 || this.pos.y > height || this.age > particleLifespan) {
      this.pos = createVector(random(width * 0.2, width * 0.8), random(height * 0.15, height * 0.85)); // Respawn in the central area
      this.vel.mult(0);
      this.age = 0;
    }
  }

  display() {
    stroke(255, map(this.age, 0, particleLifespan, 50, 0)); // White with fading trail
    strokeWeight(1);
    point(this.pos.x, this.pos.y);
  }
}

